CustomFunction.Calculation:
// Parses the HAVING clause from QueryToSQL output.
// Same approach as QueryParseWheres: extract body via QueryParseClause,
// reconstruct AND/OR from Char(29) markers, split depth-aware, iterate.
// HAVING supports: basic (col op ?) and raw (wrapped in parens).
// No BETWEEN fix needed for HAVING (BETWEEN is not a HAVING type).
Let
(
[
_body = QueryParseClause ( sql ; "HAVING" ) ;
_havingText = Substitute ( Substitute ( _body ;
	Char ( 29 ) & "AND" & Char ( 29 ) ; " AND " ) ;
	Char ( 29 ) & "OR" & Char ( 29 ) ; " OR " ) ;
_split = QueryParseSplitBooleans ( _havingText ; 0 ; 1 ; "" ) ;
_condList = Substitute ( _split ; Char ( 28 ) ; ¶ ) ;
_condCount = ValueCount ( _condList )
] ;
If ( IsEmpty ( _body ) ;
	query ;
	QueryParseHavingsIter ( query ; _condList ; _condCount ; 1 )
)
)
